  public void move(final Position from, final Position to)
  {
    if (Math.abs(from.getX() - to.getX()) + Math.abs(from.getY() - to.getY()) != 1) {
      return;
    }

    Entity fromEntity = getEntity(from);
    if (!(fromEntity instanceof Player)) {
      return;
    }
    Player player = (Player) fromEntity;
    int playerId = player.getId();

    Entity toEntity = getEntity(to);

    if (toEntity instanceof Wall || toEntity instanceof Player) {
      return;
    }

    if (toEntity == null || toEntity instanceof Empty) {
      getEntities().remove(from);
      getEntities().put(to, player);
      getCurrentTransition().add(from, to);
    } else if (toEntity instanceof Box) {
      Box box = (Box) toEntity;
      if (box.getPlayerId() != playerId) {
        return;
      }
      int dx = to.getX() - from.getX();
      int dy = to.getY() - from.getY();
      Position behind = Pa22Factory.eINSTANCE.createPosition();
      behind.setX(to.getX() + dx);
      behind.setY(to.getY() + dy);
      Entity behindEntity = getEntity(behind);
      if (behindEntity != null && !(behindEntity instanceof Empty)) {
        return;
      }
      getEntities().remove(from);
      getEntities().remove(to);
      getEntities().put(to, player);
      getEntities().put(behind, box);
      getCurrentTransition().add(from, to);
      getCurrentTransition().add(to, behind);
      checkpoint();
    }
  }

